//! Permutation-like group elements and finite groups generated by them:
//! signed permutations of algebra generators, monomial matrices with
//! root-of-unity phases, and the one group-closure routine.

use crate::algebra::FreeAlgebra;
use crate::coeff::Field;
use crate::poly::Polynomial;
use crate::word::{Var, Word};
use std::collections::{HashMap, HashSet, VecDeque};
use std::hash::Hash;

/// All elements of the group generated by `generators`, breadth first from
/// `identity` (`mul(g, p)` is `g` applied after `p`).  Panics if the group
/// has more than `limit` elements.  The one group-closure routine in ncalg.
pub fn closure<T: Clone + Eq + Hash>(
    generators: &[T],
    identity: T,
    mul: impl Fn(&T, &T) -> T,
    limit: usize,
) -> Vec<T> {
    let mut elements = vec![identity.clone()];
    let mut set: HashSet<T> = HashSet::new();
    set.insert(identity.clone());
    let mut queue = VecDeque::new();
    queue.push_back(identity);
    while let Some(p) = queue.pop_front() {
        for g in generators {
            let q = mul(g, &p);
            if set.insert(q.clone()) {
                assert!(
                    elements.len() < limit,
                    "symmetry group larger than the limit {}",
                    limit
                );
                elements.push(q.clone());
                queue.push_back(q);
            }
        }
    }
    elements
}

/// `R|x⟩ = ω^{phase[x]} |perm[x]⟩`.  [`Monomial::mul`] and [`Monomial::inv`] use `ω = e^{iπ/4}`
/// (phases mod 8); the `_bits` variants take phases mod `2^r`, `ω = e^{2πi/2^r}`.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Monomial {
    /// Image of each basis vector.
    pub perm: Vec<u32>,
    /// Phase exponent of each basis vector (a power of `ω`).
    pub phase: Vec<u8>,
}

impl Monomial {
    /// The identity on `dim` basis vectors.
    pub fn identity(dim: usize) -> Self {
        Monomial {
            perm: (0..dim as u32).collect(),
            phase: vec![0; dim],
        }
    }
    /// Number of basis vectors.
    pub fn dim(&self) -> usize {
        self.perm.len()
    }
    /// `self · b` (b acts first), phases mod 8.
    pub fn mul(&self, b: &Monomial) -> Monomial {
        self.mul_bits(b, 3)
    }
    /// The inverse, phases mod 8.
    pub fn inv(&self) -> Monomial {
        self.inv_bits(3)
    }
    /// `self · b` with phases mod `2^bits`.
    pub fn mul_bits(&self, b: &Monomial, bits: u32) -> Monomial {
        let mask = phase_mask(bits);
        let d = self.dim();
        let mut perm = vec![0u32; d];
        let mut phase = vec![0u8; d];
        for x in 0..d {
            let y = b.perm[x] as usize;
            perm[x] = self.perm[y];
            phase[x] = b.phase[x].wrapping_add(self.phase[y]) & mask;
        }
        Monomial { perm, phase }
    }
    /// Inverse with phases mod `2^bits`.
    pub fn inv_bits(&self, bits: u32) -> Monomial {
        let mask = phase_mask(bits);
        let d = self.dim();
        let mut perm = vec![0u32; d];
        let mut phase = vec![0u8; d];
        for x in 0..d {
            let y = self.perm[x] as usize;
            perm[y] = x as u32;
            phase[y] = 0u8.wrapping_sub(self.phase[x]) & mask;
        }
        Monomial { perm, phase }
    }
}

/// `2^bits - 1`; phases are stored in `u8`, so `1 ≤ bits ≤ 7`.
pub(crate) fn phase_mask(bits: u32) -> u8 {
    assert!((1..=7).contains(&bits), "phase bits must be in 1..=7");
    ((1u16 << bits) - 1) as u8
}

/// Enumerate the permutation group generated by `generators` (each a
/// permutation of `0..n` given as `perm[v] = image of v`).  Panics if the
/// group has more than `limit` elements.
pub fn permutation_group(generators: &[Vec<Var>], n: usize, limit: usize) -> Vec<Vec<Var>> {
    for g in generators {
        assert_eq!(g.len(), n, "permutation has the wrong length");
        let mut seen = vec![false; n];
        for &v in g {
            assert!((v as usize) < n && !seen[v as usize], "not a permutation");
            seen[v as usize] = true;
        }
    }
    // compose: (g ∘ p)[v] = g[p[v]]
    closure(
        generators,
        (0..n as Var).collect(),
        |g, p| p.iter().map(|&v| g[v as usize]).collect(),
        limit,
    )
}

/// Largest group whose multiplication table is built: `|G|²` entries of 8
/// bytes (2²⁶ entries, 0.5 GB; the symmetric group S_8 would need 13 GB).
pub(crate) const MULTIPLICATION_TABLE_ENTRIES: usize = 1 << 26;

/// The multiplication table of a list of signed permutations closed under
/// [`SignedPermutation::compose`]: `mul[g][h]` is the index of `group[g] ∘
/// group[h]`, and `inv[g]` the index of `group[g]`'s inverse.  `None` if the
/// list is not closed or the table would exceed
/// [`MULTIPLICATION_TABLE_ENTRIES`].
///
/// Elements are looked up by a packed key (image and sign of every
/// generator).  Products are composed into a reused buffer, with no
/// allocation, and rows are built in parallel: `|G|² · n` work.  Composing
/// through monomial matrices took 6 s for S_7.
pub(crate) fn multiplication_table(group: &[SignedPermutation]) -> Option<(Vec<Vec<usize>>, Vec<usize>)> {
    use rayon::prelude::*;
    use std::collections::HashMap;
    let g_len = group.len();
    if g_len.checked_mul(g_len)? > MULTIPLICATION_TABLE_ENTRIES {
        return None;
    }
    let key = |perm: &[Var], sign: &[i8], out: &mut Vec<u32>| {
        out.clear();
        out.extend(perm.iter().zip(sign).map(|(&p, &s)| (p << 1) | u32::from(s < 0)));
    };
    let mut index: HashMap<Vec<u32>, usize> = HashMap::with_capacity(g_len);
    let mut buf = Vec::new();
    for (i, g) in group.iter().enumerate() {
        key(&g.perm, &g.sign, &mut buf);
        index.insert(buf.clone(), i);
    }
    // (g ∘ h)[x] = g.perm[h.perm[x]], sign h.sign[x] · g.sign[h.perm[x]]
    let mul: Option<Vec<Vec<usize>>> = group
        .par_iter()
        .map(|g| {
            let mut buf: Vec<u32> = Vec::with_capacity(g.perm.len());
            group
                .iter()
                .map(|h| {
                    buf.clear();
                    buf.extend(h.perm.iter().zip(&h.sign).map(|(&y, &sh)| {
                        let y = y as usize;
                        (g.perm[y] << 1) | u32::from(sh * g.sign[y] < 0)
                    }));
                    index.get(buf.as_slice()).copied()
                })
                .collect()
        })
        .collect();
    // inverse: perm⁻¹, with sign[x] = g.sign[perm⁻¹[x]] so that g ∘ g⁻¹ = id
    let inv: Option<Vec<usize>> = group
        .iter()
        .map(|g| {
            let n = g.perm.len();
            let mut perm = vec![0 as Var; n];
            for (x, &y) in g.perm.iter().enumerate() {
                perm[y as usize] = x as Var;
            }
            let sign: Vec<i8> = (0..n).map(|x| g.sign[perm[x] as usize]).collect();
            let mut buf = Vec::new();
            key(&perm, &sign, &mut buf);
            index.get(&buf).copied()
        })
        .collect();
    Some((mul?, inv?))
}

/// A signed permutation of the generators: `x_v ↦ sign[v] · x_{perm[v]}`
/// with `sign[v] = ±1`.  Extends multiplicatively to words and linearly to
/// polynomials; it is an automorphism of the free algebra and, when it
/// preserves the ideal, of the quotient.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct SignedPermutation {
    /// Image index of each generator.
    pub perm: Vec<Var>,
    /// Sign of each image, `±1`.
    pub sign: Vec<i8>,
}

impl SignedPermutation {
    /// An unsigned permutation.
    pub fn permutation(perm: Vec<Var>) -> Self {
        let n = perm.len();
        SignedPermutation {
            perm,
            sign: vec![1; n],
        }
    }

    /// Generator-wise signs with the identity permutation (e.g. a parity
    /// `x_v ↦ −x_v` for all `v`).
    pub fn signs(sign: Vec<i8>) -> Self {
        let n = sign.len();
        SignedPermutation {
            perm: (0..n as Var).collect(),
            sign,
        }
    }

    /// Explicit permutation and signs.
    pub fn new(perm: Vec<Var>, sign: Vec<i8>) -> Self {
        assert_eq!(perm.len(), sign.len());
        assert!(sign.iter().all(|s| *s == 1 || *s == -1), "signs must be ±1");
        SignedPermutation { perm, sign }
    }

    /// The identity on `n` generators.
    pub fn identity(n: usize) -> Self {
        SignedPermutation {
            perm: (0..n as Var).collect(),
            sign: vec![1; n],
        }
    }

    fn check(&self, n: usize) {
        assert_eq!(self.perm.len(), n, "permutation has the wrong length");
        assert_eq!(self.sign.len(), n, "sign vector has the wrong length");
        let mut seen = vec![false; n];
        for &v in &self.perm {
            assert!((v as usize) < n && !seen[v as usize], "not a permutation");
            seen[v as usize] = true;
        }
    }

    /// `self ∘ other` (apply `other` first): the product of the monomial
    /// matrices with phases `±1` ([`Monomial::mul_bits`] with one phase bit).
    pub fn compose(&self, other: &SignedPermutation) -> SignedPermutation {
        SignedPermutation::from_monomial(&self.to_monomial().mul_bits(&other.to_monomial(), 1))
    }

    /// As a monomial matrix with phases mod 2 (`sign = (−1)^phase`).
    pub fn to_monomial(&self) -> Monomial {
        Monomial {
            perm: self.perm.clone(),
            phase: self.sign.iter().map(|&s| (s < 0) as u8).collect(),
        }
    }

    /// From a monomial matrix with phases mod 2.
    pub fn from_monomial(m: &Monomial) -> SignedPermutation {
        SignedPermutation {
            perm: m.perm.clone(),
            sign: m.phase.iter().map(|&p| if p & 1 == 1 { -1 } else { 1 }).collect(),
        }
    }

    /// Image of a word: `(sign, word)`.
    pub fn apply_word(&self, w: &Word) -> (i8, Word) {
        let mut s: i8 = 1;
        let img: Vec<Var> = w
            .iter()
            .map(|&v| {
                s *= self.sign[v as usize];
                self.perm[v as usize]
            })
            .collect();
        (s, Word::from_vec(img))
    }

    /// Image of a monomial as a polynomial of `alg`.
    pub fn apply_monomial<C: Field>(&self, w: &Word, alg: &FreeAlgebra) -> Polynomial<C> {
        let (s, img) = self.apply_word(w);
        alg.term(C::from_i64(s as i64), img)
    }

    /// Image of a polynomial.
    pub fn apply<C: Field>(&self, p: &Polynomial<C>, alg: &FreeAlgebra) -> Polynomial<C> {
        Polynomial::from_terms(
            alg.clone(),
            p.iter().map(|(w, c)| {
                let (s, img) = self.apply_word(w);
                (img, if s == 1 { c.clone() } else { c.negated() })
            }),
        )
    }
}

/// Enumerate the group generated by signed permutations.  Panics if it has
/// more than `limit` elements.
pub fn signed_permutation_group(
    generators: &[SignedPermutation],
    n: usize,
    limit: usize,
) -> Vec<SignedPermutation> {
    for g in generators {
        g.check(n);
    }
    closure(
        generators,
        SignedPermutation::identity(n),
        |g, p| g.compose(p),
        limit,
    )
}

/// Cyclic rotation `i ↦ i+1 (mod n)` acting on generator indices of a
/// `FreeAlgebra` whose generators are named `s{i}{j}` for pairs `i < j`
/// (as produced by the swap-algebra examples); returns the generator
/// permutation.  Convenience for dihedral symmetry of cycle Hamiltonians.
pub fn pair_permutation(n: usize, site_perm: &dyn Fn(usize) -> usize) -> Vec<Var> {
    let mut pairs = Vec::new();
    for i in 1..=n {
        for j in (i + 1)..=n {
            pairs.push((i, j));
        }
    }
    let index: HashMap<(usize, usize), Var> = pairs.iter().enumerate().map(|(k, &p)| (p, k as Var)).collect();
    pairs
        .iter()
        .map(|&(i, j)| {
            let (a, b) = (site_perm(i), site_perm(j));
            index[&(a.min(b), a.max(b))]
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn closures_and_composition() {
        // S3 on 3 points
        let s3 = permutation_group(&[vec![1, 2, 0], vec![1, 0, 2]], 3, 100);
        assert_eq!(s3.len(), 6);
        // a 4-cycle with one sign has order 8 (r^4 = −1); with the reflection: 64 elements
        let r = SignedPermutation::new(vec![1, 2, 3, 0], vec![1, 1, 1, -1]);
        let f = SignedPermutation::new(vec![0, 3, 2, 1], vec![1, 1, 1, 1]);
        assert_eq!(
            signed_permutation_group(&[r.clone(), f.clone()], 4, 1000).len(),
            64
        );
        // the square's dihedral group times a global sign: 16 elements
        let rot = SignedPermutation::permutation(vec![1, 2, 3, 0]);
        let parity = SignedPermutation::signs(vec![-1; 4]);
        assert_eq!(
            signed_permutation_group(&[rot, f.clone(), parity], 4, 1000).len(),
            16
        );
        // compose agrees with x_v -> sign[v] x_perm[v] applied twice
        let rf = r.compose(&f);
        for v in 0..4 {
            let (s1, w1) = (f.sign[v], f.perm[v] as usize);
            assert_eq!(rf.perm[v] as usize, r.perm[w1] as usize);
            assert_eq!(rf.sign[v], s1 * r.sign[w1]);
        }
        assert_eq!(SignedPermutation::from_monomial(&r.to_monomial()), r);
    }
}
